# Rebuild evidence from recorded saves and screenshots only; no original-game input.
$ErrorActionPreference='Stop'
$project=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path;$runtime=Join-Path $project '.local-research/runtime';$dir=Join-Path $project 'docs/research/rimworld/evidence';$utf8=[Text.UTF8Encoding]::new($false)
$reader=Join-Path $PSScriptRoot 'read-plants-runtime-save.ps1'
$snapshots=@(foreach($name in @('stonecutting-final','plants-entry-a','plants-entry-b','plants-start','plants-ready-a','plants-ready-b','plants-stopped-a','plants-stopped-b')){$relative=".local-research/runtime/profile-20261102/Saves/$name.rws";[ordered]@{name=$name;path=$relative;save=(& $reader -SavePath (Join-Path $project $relative)|ConvertFrom-Json)}})
Add-Type -AssemblyName System.Drawing
$specs=@(
 @('baseline-load','plants-003-load-dialog.png',960,360,640,710,'Original isolated load dialog includes stonecutting-final; subsequent action clicks its Load button.'),
 @('loaded','plants-005-loaded.png',0,1100,2560,340,'Loaded original colony before plant observations; time later shown to have resumed automatically.'),
 @('cactus38','plants-006-cactus-a.png',0,1230,620,180,'Saguaro cactus:130/130 health,38% grown; growth0% resting/needs light level51%; Chop wood button.'),
 @('cactus71','plants-009-cactus-second.png',0,1230,620,180,'Saguaro cactus:90/130 health (69%),71% grown; growth100%; Chop wood button.'),
 @('growing-zone','plants-015-select-growing.png',0,1230,1000,180,'Growing zone1,Size1,growing period50/60days; default Potato; Allow sowing/cutting controls.'),
 @('sow-menu','plants-016-sow-menu.png',800,1020,280,420,'Fourteen visible non-tree crop choices, including explicit minimum-skill labels; no tree disabled-reason popup.'),
 @('failed-chop-attempt','plants-022-chop-menu.png',0,1230,2560,180,'Actual result of attempted chop navigation: Growing zone2 selected and hidden, not a pawn chop context menu.'),
 @('final-paused','plants-stopped-b-return.png',1800,920,760,520,'Final stopped-b colony view; two end saves confirm tick64249 unchanged.')
)
$shots=@();foreach($row in $specs){$source=Join-Path $runtime $row[1];$relative="runtime/plants-$($row[0]).png";$destination=Join-Path $dir $relative;$bmp=[Drawing.Bitmap]::new($source);try{$crop=$bmp.Clone([Drawing.Rectangle]::new($row[2],$row[3],$row[4],$row[5]),$bmp.PixelFormat);try{$crop.Save($destination,[Drawing.Imaging.ImageFormat]::Png)}finally{$crop.Dispose()}}finally{$bmp.Dispose()};$capture=Get-Content -LiteralPath ($source+'.jsonl')|Select-Object -Last 1|ConvertFrom-Json;$shots+=[ordered]@{id=$row[0];image=$relative;sha256=(Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash.ToLowerInvariant();source_file=".local-research/runtime/$($row[1])";source_sha256=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash.ToLowerInvariant();source_size=@(2560,1440);crop_xywh=@($row[2],$row[3],$row[4],$row[5]);observed_utc=$capture.timestamp_utc;observation=$row[6]}}
$actions=@(Get-ChildItem -LiteralPath $runtime -Filter 'plants-*.png.actions.jsonl'|ForEach-Object{Get-Content -LiteralPath $_.FullName|ForEach-Object{[ordered]@{kind='guarded-ui-input';data=($_|ConvertFrom-Json)}}}|Sort-Object {$_.data.started_utc});$actionPath=Join-Path $dir 'native-plants-actions.jsonl';[IO.File]::WriteAllText($actionPath,(($actions|ForEach-Object{ConvertTo-Json $_ -Depth 10 -Compress}) -join "`n")+"`n",$utf8)
$record=[ordered]@{schema_version=1;evidence_id='RW17-NATIVE-PLANTS-RUNTIME';version_text='1.7.4980 rev60';assembly_sha256='eff7d97949f919fb2b151ebfb906e9be749b63410b7dbda78eeebb7972b245c3';process_id=29920;profile='.local-research/runtime/profile-20261102';active_mods=@('ludeon.rimworld','ludeon.rimworld.odyssey');rea=@{skill_version=42;server_version='6.7.0';session_open=$false;native_ui_provider='unsupported_host: native macOS utilities require macOS';runtime_method='Existing guarded Windows foreground mouse/keyboard screenshot helper; not REA native UI execution.'};snapshots=$snapshots
 ui_samples=@(@{shot='cactus38';plant='Saguaro cactus';health=130;max_health=130;growth_percent=38;growth_rate_percent=0;growth_reason='resting, needs light level 51%';chop_wood_button_visible=$true},@{shot='cactus71';plant='Saguaro cactus';health=90;max_health=130;health_percent_displayed=69;growth_percent=71;growth_rate_percent=100;chop_wood_button_visible=$true})
 visible_sow_menu=@('Corn plant','Haygrass','Potato plant','Rice plant','Strawberry plant (min skill: 5)','Healroot (min skill: 8)','Dandelions','Daylily','Rose','Cotton plant','Hop plant (min skill: 3)','Psychoid plant (min skill: 6)','Smokeleaf plant (min skill: 4)','Tinctoria')
 clock=@{entry_ticks=@(134003,134003);baseline_tick=50881;start_after_load_tick=55840;ready_ticks=@(64249,64249);final_ticks=@(64249,64249);unplanned_post_load_advance=13368;controlled_paused_phase_delta=0;deliberate_run_windows=0;final_pause_verified=$true}
 outcomes=@{different_growth_percentages_observed=$true;health_growth_distinction_observed=$true;chop_button_observed=$true;growing_zone_created=$true;crop_min_skill_labels_observed=$true;tree_option_selected=$false;tree_disabled_reason_popup_observed=$false;sowing_eligibility_exercised=$false;normal_tree_chop_started=$false;normal_tree_chop_finished=$false;harvest_yield_observed=$false;harvest_work_time_observed=$false;controlled_growth_experiment=$false;multi_season_growth_observed=$false}
 screenshots=$shots;actions=@{file='native-plants-actions.jsonl';sha256=(Get-FileHash -LiteralPath $actionPath -Algorithm SHA256).Hash.ToLowerInvariant();count=$actions.Count}
 limitations=@('Actual UI window20:57:32-21:15:21UTC, approximately18minutes including pause/load/save verification; no further UI input afterward.','Loading stonecutting-final resumed the original game clock automatically. plants-start55840 and ready64249 are not a controlled growth experiment. No speed3 or developer time-increment command was sent.','The damaged134003 branch was saved under entry-a/b for pause verification only; plant observations followed explicit loading of intact stonecutting-final.','No plant, skill or research developer preparation was performed this round. Developer mode/God mode were already enabled; the inherited baseline includes earlier unrelated developer preparation.','The38% and71% screenshots are two different natural saguaro cacti at different observation times, not a single plant growth timelapse or complete tree-species survey.','Visible crop menu contains14 non-tree entries; no tree rejection tooltip was observed. TreeSowing progress0 and pawn Plants levels are save context only, not an isolated causal test.','A later attempted chop navigation failed because the growing-zone designator remained active. It created/selected another one-cell Potato zone and toggled its visibility. Screenshot filenames mentioning chop describe intent, not successful chopping.','Final XML contains two one-cell Potato growing zones, second hidden, and no designations. No harvesting or sowing job was executed; resource yield, work duration and worker eligibility remain unverified.','Portable checks validate recorded summaries/crop/ledger integrity. Local mode re-reads originals. Neither performs OCR, reruns gameplay, or turns incomplete UI coverage into a mechanics proof.')
 final_state=@{paused=$true;pause_confirmed_by_two_equal_saves=$true;canonical_save='plants-stopped-b.rws';baseline_untouched=$true;normal_profile_touched=$false;game_files_modified=$false;mods_installed=$false;developer_mode=$true;god_mode=$true}}
[IO.File]::WriteAllText((Join-Path $dir 'native-plants-runtime.json'),(ConvertTo-Json $record -Depth 24)+"`n",$utf8)
"Collected $($snapshots.Count) save summaries, $($shots.Count) crops, $($actions.Count) actions. No harvest/sow execution demonstrated."
